import{_ as t,o,c as a,a2 as i}from"./chunks/framework.DBSoX6Zw.js";const u=JSON.parse('{"title":"Security","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security.md","filePath":"guide/security.md"}'),s={name:"guide/security.md"};function n(r,e,d,l,c,p){return o(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h1><p>Plik allows users to upload and serve any content as-is. Hosting untrusted content raises security concerns that Plik addresses with several mechanisms.</p><h2 id="content-type-override" tabindex="-1">Content-Type Override <a class="header-anchor" href="#content-type-override" aria-label="Permalink to &quot;Content-Type Override&quot;">​</a></h2><p>For security reasons, Plik doesn&#39;t trust user-provided MIME types and relies solely on server-side detection. This means some files may not render properly in browsers or embedded viewers that require the correct MIME type.</p><h3 id="dangerous-content-type-neutralization" tabindex="-1">Dangerous Content-Type Neutralization <a class="header-anchor" href="#dangerous-content-type-neutralization" aria-label="Permalink to &quot;Dangerous Content-Type Neutralization&quot;">​</a></h3><p>Plik automatically neutralizes content types that could execute code in the browser:</p><table tabindex="0"><thead><tr><th>Original type</th><th>Served as</th><th>Reason</th></tr></thead><tbody><tr><td><code>text/html</code>, <code>*html*</code></td><td><code>application/octet-stream</code></td><td>Prevents inline script execution</td></tr><tr><td><code>image/svg+xml</code>, <code>*svg*</code></td><td><code>application/octet-stream</code></td><td>SVG can contain <code>onload</code> JavaScript handlers</td></tr><tr><td><code>text/xml</code>, <code>*xml*</code></td><td><code>application/octet-stream</code></td><td>XML can be parsed and rendered by browsers</td></tr><tr><td><code>application/javascript</code>, <code>*javascript*</code></td><td><code>application/octet-stream</code></td><td>Prevents script execution</td></tr><tr><td><code>application/x-shockwave-flash</code></td><td><code>application/octet-stream</code></td><td>Flash content</td></tr><tr><td><code>application/pdf</code></td><td><code>application/octet-stream</code></td><td>PDF can contain JavaScript</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This protection is always active regardless of <code>EnhancedWebSecurity</code>. Use the <code>?dl=true</code> query parameter to force a download with <code>Content-Disposition: attachment</code>.</p></div><div class="warning custom-block"><p class="custom-block-title">Office format detection limitation</p><p>Office formats like <code>.pptx</code>, <code>.docx</code>, and <code>.xlsx</code> are ZIP archives internally, so Go&#39;s built-in MIME detector (<code>http.DetectContentType</code>) identifies them as <code>application/zip</code> instead of their proper types (e.g., <code>application/vnd.openxmlformats-officedocument.presentationml.presentation</code>).</p></div><h2 id="enhanced-web-security" tabindex="-1">Enhanced Web Security <a class="header-anchor" href="#enhanced-web-security" aria-label="Permalink to &quot;Enhanced Web Security&quot;">​</a></h2><p>When <code>EnhancedWebSecurity</code> is enabled in <code>plikd.cfg</code>, Plik sets additional HTTP headers:</p><ul><li><strong>X-Content-Type-Options</strong>: <code>nosniff</code></li><li><strong>X-XSS-Protection</strong>: enabled</li><li><strong>X-Frame-Options</strong>: deny</li><li><strong>Content-Security-Policy</strong>: restrictive policy disabling resource loading, XHR, iframes</li><li><strong>Strict-Transport-Security</strong>: <code>max-age=31536000</code> (1 year) — also set when <code>SslEnabled</code> is true</li><li><strong>Secure Cookies</strong>: session cookies only transmitted over HTTPS — also set when <code>SslEnabled</code> is true</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Enhanced security will break audio/video playback, PDF rendering, and other rich content features. Disable it if you need those capabilities.</p></div><div class="danger custom-block"><p class="custom-block-title">Authentication requires HTTPS with Secure Cookies</p><p>When <code>EnhancedWebSecurity</code> or <code>SslEnabled</code> is enabled, session cookies have the <code>Secure</code> flag set and can only be transmitted over HTTPS connections. Authentication will not work over plain HTTP.</p></div><h2 id="upload-password-protection" tabindex="-1">Upload Password Protection <a class="header-anchor" href="#upload-password-protection" aria-label="Permalink to &quot;Upload Password Protection&quot;">​</a></h2><p>When <code>FeaturePassword</code> is enabled, uploads can be protected with a login/password pair. Credentials are transmitted via HTTP Basic Authentication.</p><p>Passwords are hashed using <strong>bcrypt(sha256(credentials))</strong> before storage; the plaintext is never persisted. The SHA-256 pre-hash ensures credentials of any length are securely handled within bcrypt&#39;s input constraints.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Limit</th></tr></thead><tbody><tr><td>Login</td><td>128 characters max</td></tr><tr><td>Password</td><td>128 characters max</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Legacy uploads (created before version 1.4) use MD5 hashing and continue to work until they expire.</p></div><h2 id="removable-uploads" tabindex="-1">Removable Uploads <a class="header-anchor" href="#removable-uploads" aria-label="Permalink to &quot;Removable Uploads&quot;">​</a></h2><p>When <code>FeatureRemovable</code> is enabled and an upload is created with <code>removable: true</code>, <strong>anyone with the upload URL can delete the upload and its files</strong> — no upload token or authentication is required. This is by design: the <code>removable</code> flag is intended for ephemeral, public uploads where ease of cleanup is prioritized over access control.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If you need to control who can delete an upload, do <strong>not</strong> set <code>removable: true</code>. Only the upload owner (via upload token, API token, or session) can delete non-removable uploads.</p></div><h2 id="download-domain" tabindex="-1">Download Domain <a class="header-anchor" href="#download-domain" aria-label="Permalink to &quot;Download Domain&quot;">​</a></h2><p>It is recommended to serve uploaded files on a separate (sub-)domain to:</p><ul><li>Protect against phishing links using your main domain</li><li>Protect Plik&#39;s session cookie from being exposed to uploaded content</li><li>Prevent uploaded JavaScript from making API calls as the authenticated user</li></ul><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><p>When using a download domain, three configuration options work together:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PlikDomain     = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://plik.root.gg&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # Main webapp URL (recommended when DownloadDomain is set)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DownloadDomain = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://dl.plik.root.gg&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Separate domain for serving files</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DownloadDomainAlias = []                       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Additional accepted download hosts</span></span></code></pre></div><p><strong><code>PlikDomain</code></strong> — The public URL where the webapp is served. When set:</p><ul><li>OAuth redirect URLs use this domain instead of the <code>Referer</code> header</li><li><code>GetServerURL()</code> returns this domain for CLI quick upload URLs</li><li>CORS headers are configured when <code>DownloadDomain</code> is also set</li></ul><div class="tip custom-block"><p class="custom-block-title">PlikDomain does not restrict downloads</p><p>Setting <code>PlikDomain</code> alone does <strong>not</strong> enforce any domain check on file downloads — files remain accessible from any host. To restrict downloads to a specific domain, you must also set <code>DownloadDomain</code>.</p></div><p><strong><code>DownloadDomain</code></strong> — The domain that serves uploaded files. When set:</p><ul><li>File/archive download requests are rejected unless the <code>Host</code> header matches the download domain (or an alias)</li><li>Non-file requests (webapp UI, API) on the download domain are <strong>blocked</strong> to prevent security issues (see below)</li><li>Set <code>PlikDomain</code> too to enable CORS and redirect behavior</li></ul><p><strong><code>DownloadDomainAlias</code></strong> — Additional hostnames accepted for file downloads. Useful when:</p><ul><li>Accessing the server via <code>localhost</code> during development</li><li>The reverse proxy uses a different host internally</li></ul><h3 id="security-ui-restriction-on-download-domain" tabindex="-1">Security: UI Restriction on Download Domain <a class="header-anchor" href="#security-ui-restriction-on-download-domain" aria-label="Permalink to &quot;Security: UI Restriction on Download Domain&quot;">​</a></h3><p>When <code>DownloadDomain</code> is configured, Plik <strong>blocks</strong> the webapp UI and API endpoints from being served on the download domain. This is critical because:</p><ul><li>An attacker could share a link like <code>https://dl.plik.root.gg/</code> — the user sees the familiar Plik UI but on the download domain</li><li>If the user logs in on this domain, their session cookie is exposed to uploaded content</li><li>Uploaded JavaScript could make authenticated API calls on behalf of the user</li></ul><p><strong>How it works:</strong></p><table tabindex="0"><thead><tr><th>Request type</th><th>Download domain behavior</th></tr></thead><tbody><tr><td>File/stream/archive</td><td>✅ Served normally</td></tr><tr><td><code>/health</code></td><td>✅ Served normally (for load balancer probes)</td></tr><tr><td>Everything else (UI, API)</td><td>🔄 Redirect to <code>PlikDomain</code> (or 403 if not set)</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Ideal setup — use both domains</p><p>For the best security and user experience, configure <strong>both</strong> <code>PlikDomain</code> and <code>DownloadDomain</code>:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PlikDomain     = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://plik.root.gg&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DownloadDomain = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://dl.plik.root.gg&quot;</span></span></code></pre></div><p>This gives you:</p><ul><li><strong>Domain isolation</strong>: uploaded files served separately from the webapp</li><li><strong>Smooth redirects</strong>: users who land on the download domain are redirected to the webapp</li><li><strong>CORS support</strong>: the file viewer and E2EE decrypt work cross-origin</li><li><strong>Reliable OAuth</strong>: redirect URLs use PlikDomain instead of the fragile Referer header</li></ul><p>Without <code>PlikDomain</code>, non-file requests on the download domain return <strong>403 Forbidden</strong> instead of redirecting.</p></div><div class="info custom-block"><p class="custom-block-title">How CORS works here</p><p>When both domains are configured, Plik adds <code>Access-Control-Allow-Origin: &lt;PlikDomain&gt;</code> headers to download responses. This allows the webapp&#39;s JavaScript to fetch file content cross-origin (for the file viewer and E2EE decrypt), while still preventing uploaded JavaScript on the download domain from accessing the webapp&#39;s origin.</p></div><h3 id="troubleshooting-redirect-loops" tabindex="-1">Troubleshooting: Redirect Loops <a class="header-anchor" href="#troubleshooting-redirect-loops" aria-label="Permalink to &quot;Troubleshooting: Redirect Loops&quot;">​</a></h3><p>If you see this error:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Invalid download domain 127.0.0.1:8080, expected plik.root.gg</span></span></code></pre></div><p><code>DownloadDomain</code> checks the <code>Host</code> header of incoming HTTP requests. By default, reverse proxies like Nginx and Apache do not forward this header. Make sure to configure:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Apache mod_proxy: ProxyPreserveHost On</span></span>
<span class="line"><span>Nginx:            proxy_set_header Host $host;</span></span></code></pre></div><h2 id="xsrf-protection" tabindex="-1">XSRF Protection <a class="header-anchor" href="#xsrf-protection" aria-label="Permalink to &quot;XSRF Protection&quot;">​</a></h2><p>Plik uses a dual-cookie XSRF protection mechanism:</p><ol><li>The <code>plik-xsrf</code> cookie value must be copied into the <code>X-XSRFToken</code> HTTP header for all mutating authenticated requests</li><li>This prevents cross-site request forgery attacks</li></ol><h2 id="upload-restrictions" tabindex="-1">Upload Restrictions <a class="header-anchor" href="#upload-restrictions" aria-label="Permalink to &quot;Upload Restrictions&quot;">​</a></h2><h3 id="source-ip-whitelist" tabindex="-1">Source IP Whitelist <a class="header-anchor" href="#source-ip-whitelist" aria-label="Permalink to &quot;Source IP Whitelist&quot;">​</a></h3><p>Restrict uploads and user creation to specific IP ranges:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UploadWhitelist = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;10.0.0.0/8&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;192.168.1.0/24&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><h3 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h3><p>Set <code>FeatureAuthentication = &quot;forced&quot;</code> to require authentication for all uploads.</p><h3 id="upload-tokens" tabindex="-1">Upload Tokens <a class="header-anchor" href="#upload-tokens" aria-label="Permalink to &quot;Upload Tokens&quot;">​</a></h3><p>Authenticated users can generate upload tokens to link CLI uploads to their account. Tokens are sent via the <code>X-PlikToken</code> HTTP header.</p><h2 id="link-preview-bot-protection" tabindex="-1">Link Preview Bot Protection <a class="header-anchor" href="#link-preview-bot-protection" aria-label="Permalink to &quot;Link Preview Bot Protection&quot;">​</a></h2><p>Messaging apps like Slack, Telegram, WhatsApp, Signal, Discord, and others generate link previews by fetching shared URLs. This is problematic for:</p><ul><li><strong>One-shot uploads</strong>: the bot&#39;s preview request counts as the single allowed download, deleting the file before the intended recipient can access it</li><li><strong>Streaming uploads</strong>: the bot consumes the stream data, leaving nothing for the real downloader</li></ul><p>Plik automatically blocks known messaging app link preview bots from downloading one-shot and streaming files, returning a <strong>406 Not Acceptable</strong> response. Normal (multi-download) uploads are not affected — bots can still generate previews for those.</p><div class="tip custom-block"><p class="custom-block-title">No configuration needed</p><p>This protection is always active and requires no configuration. It uses a hardcoded list of known bot user-agent strings that is maintained with Plik releases.</p></div><h3 id="blocked-bots" tabindex="-1">Blocked Bots <a class="header-anchor" href="#blocked-bots" aria-label="Permalink to &quot;Blocked Bots&quot;">​</a></h3><p>Slack, Telegram, WhatsApp, Signal, Facebook/Messenger, Discord, Skype, Viber, LinkedIn, Twitter/X, Microsoft Teams, Wire, Mattermost, Rocket.Chat, and Zulip.</p><h2 id="server-side-encryption-s3" tabindex="-1">Server-Side Encryption (S3) <a class="header-anchor" href="#server-side-encryption-s3" aria-label="Permalink to &quot;Server-Side Encryption (S3)&quot;">​</a></h2><p>When using the S3 data backend, Plik supports server-side encryption to protect uploaded files at rest.</p><h3 id="encryption-modes" tabindex="-1">Encryption Modes <a class="header-anchor" href="#encryption-modes" aria-label="Permalink to &quot;Encryption Modes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mode</th><th>Key Management</th><th>Description</th></tr></thead><tbody><tr><td><code>S3</code></td><td>S3 backend</td><td>The S3 service manages encryption keys transparently</td></tr><tr><td><code>SSE-C</code></td><td>Plik</td><td>Plik generates a unique 32-byte key per file</td></tr></tbody></table><h3 id="sse-c-threat-model" tabindex="-1">SSE-C Threat Model <a class="header-anchor" href="#sse-c-threat-model" aria-label="Permalink to &quot;SSE-C Threat Model&quot;">​</a></h3><p>With <code>SSE-C</code>, encryption keys are generated by Plik and stored in the <strong>metadata database</strong> (in the <code>BackendDetails</code> column of each file record).</p><div class="warning custom-block"><p class="custom-block-title">Security boundary</p><p>SSE-C protects against <strong>S3 bucket compromise in isolation</strong> — if an attacker gains access to the S3 storage but not the metadata database, uploaded files remain encrypted and unreadable.</p><p>However, if both the S3 bucket <strong>and</strong> the metadata database are compromised, the attacker can retrieve the encryption keys and decrypt all files.</p></div><p><strong>Recommendations:</strong></p><ul><li>For maximum security, host the metadata database on <strong>separate infrastructure</strong> from the S3 storage</li><li>If both are co-located (e.g., SQLite + local MinIO on the same host), SSE-C provides limited additional protection</li><li>Consider <code>S3</code> mode if your S3 provider already offers robust at-rest encryption with their own key management</li></ul>`,74)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
